func TestGenFrrStaticRoute(t *testing.T) {
	fake := opnsensetest.New(t)
	h := newHarness(t, fake, NewFrrStaticRouteResource())
	plan := genFrrStaticRoutePlan()
	var got genFrrStaticRouteModel
	st, ok := h.create(plan, &got)
	if !ok {
		t.Fatal("create failed")
	}
	id := got.ID.ValueString()
	rec, ok := fake.Get("route", id)
	if !ok {
		t.Fatal("not stored")
	}
	if !sameValues(rec["enabled"], "1") {
		t.Errorf("enabled: stored %q, want %q", rec["enabled"], "1")
	}
	if !sameValues(rec["network"], "10.9.0.0/24") {
		t.Errorf("network: stored %q, want %q", rec["network"], "10.9.0.0/24")
	}
	if !sameValues(rec["gateway"], "192.168.1.2") {
		t.Errorf("gateway: stored %q, want %q", rec["gateway"], "192.168.1.2")
	}
	if !sameValues(rec["interfacename"], "") {
		t.Errorf("interfacename: stored %q, want %q", rec["interfacename"], "")
	}
	if !sameValues(rec["bfd"], "0") {
		t.Errorf("bfd: stored %q, want %q", rec["bfd"], "0")
	}

	plan.ID = got.ID
	plan.Enabled = types.BoolValue(false)
	st = h.update(st, plan, &got)
	rec, _ = fake.Get("route", id)
	if !sameValues(rec["enabled"], "0") {
		t.Errorf("enabled: stored %q, want %q", rec["enabled"], "0")
	}

	if _, ok := h.read(st, &got); !ok {
		t.Fatal("read removed the resource")
	}
	if imp, ok := h.importID(id); !ok || imp != id {
		t.Fatalf("import by uuid = %q", imp)
	}
	if imp, ok := h.importID("10.9.0.0/24"); !ok || imp != id {
		t.Fatalf("import by name = %q", imp)
	}
	h.delete(st)
	if _, ok := fake.Get("route", id); ok {
		t.Fatal("still stored after delete")
	}
	if fake.Applies["quagga/service/reconfigure"] == 0 {
		t.Error("never applied")
	}
}

